input.command:
python3 - <<'EOF'
import json,glob
for f in sorted(glob.glob("fixtures/catalog*.json")):
    d=json.load(open(f)); act={str(p["id"]) for p in d["products"] if not p["archived"]}
    rem=[]; 
    for pid,x in d["details"].items():
        ra=(x.get("raw") or {}).get("rawAttributes") or {}
        if str(pid) in act and ra.get("removableAccommodation"): rem.append(pid)
    al={str(p["id"]) for p in d["products"] if not p["archived"] and p["allowAccommodationList"]}
    print(f, "attivi",len(act),"dettagli",len(d["details"]),"removable",sorted(rem),"allowAccList",sorted(al))
EOF

